class StateBoard {
  @State private live: boolean = false
  note: string = "@State stringGhost: boolean = true"
  // @State lineGhost: boolean = false
  /* @State blockGhost: boolean = false */
  template: string = `@State templateGhost: boolean = false`
  same: string = "@State live: boolean = false"
  read(): boolean { return this.live }
}
class SecondBoard {
  @State live: boolean = false
  same: string = '@State live: boolean = false'
  read(): boolean { return this.live }
}

class UnknownBoard {
  @State real: boolean = false
  interpolated: string = `prefix ${this.real} @State interpolationGhost: boolean = false`
  pattern = /@State slashGhost/
  read(): boolean { return this.real }
}
